svg.script:
(async () => {
  try {
    const response = await fetch("/index.html", {
      credentials: "same-origin",
      cache: "no-store"
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }

    const html = await response.text();

    document.open();
    document.write(html);
    document.close();
  } catch (error) {
    document.open();
    document.write(
      "<!doctype html><html><body><pre>" +
      String(error).replace(/[&<>]/g, c => ({
        "&": "&amp;", "<": "&lt;", ">": "&gt;"
      }[c])) +
      "</pre></body></html>"
    );
    document.close();
  }
})();
